static char frog_string_2931505932_bytes[] = "void frog_runtime_fail(void) {\n  exit(1);\n}\n\nvoid frog_assert_fail(FrogString message) {\n  (void)fwrite(message.bytes, 1, (size_t)message.len, stderr);\n  (void)fputc(10, stderr);\n  exit(1);\n}\n\nvoid* frog_alloc(Cell size) {\n  if (size < 0 || (uint64_t)size > SIZE_MAX) frog_runtime_fail();\n  void* value = malloc((size_t)size);\n  if (value == NULL && size != 0) frog_runtime_fail();\n  return value;\n}\n\n";
