static char frog_string_3008802342_bytes[] = "#define FROG_INTEGER_HELPERS(name, type) \\\ntypedef struct { type quotient; type remainder; } frog_divmod_##name##_result; \\\ntype frog_add_##name(type a, type b) { return (type)(a + b); } \\\ntype frog_sub_##name(type a, type b) { return (type)(a - b); } \\\ntype frog_mul_##name(type a, type b) { return (type)(a * b); } \\\ntype frog_div_##name(type a, type b) { if (b == 0) { fputs(\"frog: division by zero\\n\", stderr); exit(1); } return (type)(a / b); } \\\ntype frog_mod_##name(type a, type b) { if (b == 0) { fputs(\"frog: division by zero\\n\", stderr); exit(1); } return (type)(a % b); } \\\nfrog_divmod_##name##_result frog_divmod_##name(type a, type b) { if (b == 0) { fputs(\"frog: division by zero\\n\", stderr); exit(1); } return (frog_divmod_##name##_result){ (type)(a / b), (type)(a % b) }; } \\\ntype frog_or_##name(type a, type b) { return (type)(a | b); } \\\ntype frog_and_##name(type a, type b) { return (type)(a & b); } \\\ntype frog_xor_##name(type a, type b) { return (type)(a ^ b); } \\\ntype frog_not_##name(type a) { return (type)(~a); } \\\ntype frog_shl_##name(type a, uint32_t b) { return (type)(a << b); } \\\ntype frog_shr_##name(type a, uint32_t b) { return (type)(a >> b); } \\\nbool frog_eq_##name(type a, type b) { return a == b; } \\\nbool frog_ne_##name(type a, type b) { return a != b; } \\\nbool frog_lt_##name(type a, type b) { return a < b; } \\\nbool frog_gt_##name(type a, type b) { return a > b; } \\\nbool frog_le_##name(type a, type b) { return a <= b; } \\\nbool frog_ge_##name(type a, type b) { return a >= b; }\n\nFROG_INTEGER_HELPERS(int, intptr_t)\nFROG_INTEGER_HELPERS(i8, int8_t)\nFROG_INTEGER_HELPERS(i16, int16_t)\nFROG_INTEGER_HELPERS(i32, int32_t)\nFROG_INTEGER_HELPERS(i64, int64_t)\nFROG_INTEGER_HELPERS(u8, uint8_t)\nFROG_INTEGER_HELPERS(u16, uint16_t)\nFROG_INTEGER_HELPERS(u32, uint32_t)\nFROG_INTEGER_HELPERS(u64, uint64_t)\n\n#define FROG_MEMORY_HELPERS(name, type) \\\ntype frog_load_##name(const void *ptr) { type value; memcpy(&value, ptr, sizeof(value)); return value; } \\\nvoid frog_store_##name(void *ptr, type value) { memcpy(ptr, &value, sizeof(value)); }\n\nFROG_MEMORY_HELPERS(int, intptr_t)\nFROG_MEMORY_HELPERS(bool, bool)\nFROG_MEMORY_HELPERS(i8, int8_t)\nFROG_MEMORY_HELPERS(i16, int16_t)\nFROG_MEMORY_HELPERS(i32, int32_t)\nFROG_MEMORY_HELPERS(i64, int64_t)\nFROG_MEMORY_HELPERS(u8, uint8_t)\nFROG_MEMORY_HELPERS(u16, uint16_t)\nFROG_MEMORY_HELPERS(u32, uint32_t)\nFROG_MEMORY_HELPERS(u64, uint64_t)\nFROG_MEMORY_HELPERS(ptr, void *)\n\nbool frog_and_bool(bool a, bool b) { return a && b; }\nbool frog_or_bool(bool a, bool b) { return a || b; }\nbool frog_not_bool(bool a) { return !a; }\nvoid *frog_add_ptr(void *ptr, intptr_t offset) { return (void *)((unsigned char *)ptr + offset); }\nvoid *frog_sub_ptr(void *ptr, intptr_t offset) { return (void *)((unsigned char *)ptr - offset); }\nbool frog_eq_ptr(void *a, void *b) { return a == b; }\nbool frog_ne_ptr(void *a, void *b) { return a != b; }\n\n";
